// @generated by:gauntlet run:godseye-local-broker
import { randomUUID } from "node:crypto";
import type { CreateServiceIdentityInput } from "@godseye/contracts";
import { ControlPlane } from "@godseye/core";
import { schema } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AccessFixture, accessFixture, prepareAccess } from "./access-helpers.js";
import { owner, projectInput } from "./helpers.js";

// Exercise runtime validation with intentionally malformed external JSON, beyond the compile-time DTO.
const untrustedIdentity = (input: unknown) => input as CreateServiceIdentityInput;

describe("exact-cell service identity authority", () => {
  let fixture: AccessFixture;
  beforeEach(async () => {
    fixture = await accessFixture();
  });
  afterEach(async () => {
    await fixture?.store.close();
  });

  it("T-AC-14 T22 rejects service administration and stale owner verification", async () => {
    const service = {
      id: "fixture-service",
      kind: "service" as const,
      projectIds: [fixture.project.id],
    };
    await expect(fixture.broker.overview(service)).rejects.toMatchObject({ status: 403 });
    await expect(
      fixture.broker.createIdentity(
        service,
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          purpose: "runtime",
          name: "Denied",
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    const stale = fixture.freshOwner();
    fixture.clock.advance(300_001);
    await expect(
      fixture.broker.createIdentity(
        stale,
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          purpose: "runtime",
          name: "Denied stale",
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    expect((await fixture.broker.overview(fixture.freshOwner())).identities).toHaveLength(0);
  });

  it("T-AC-14 T34 refuses an environment that belongs to another project", async () => {
    const other = await new ControlPlane(fixture.store).createProject(
      owner,
      { ...projectInput, slug: "foreign-access" },
      randomUUID(),
    );
    const environment = other.environments[0];
    if (!environment) throw new Error("Foreign fixture environment missing");
    await expect(
      fixture.broker.createIdentity(
        fixture.freshOwner(),
        {
          projectId: fixture.project.id,
          environmentId: environment.id,
          purpose: "runtime",
          name: "Wrong ancestry",
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    expect((await fixture.broker.overview(fixture.freshOwner())).identities).toHaveLength(0);
  });

  it("T-AC-15 T22 requires a fixed worker for task purposes and forbids it for static runtime", async () => {
    for (const purpose of ["migration", "deploy", "backup"] as const) {
      await expect(
        fixture.broker.createIdentity(
          fixture.freshOwner(),
          untrustedIdentity({
            projectId: fixture.project.id,
            environmentId: fixture.development.id,
            purpose,
            name: "No worker",
          }),
          randomUUID(),
        ),
      ).rejects.toMatchObject({ status: 422 });
    }
    await expect(
      fixture.broker.createIdentity(
        fixture.freshOwner(),
        untrustedIdentity({
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          purpose: "runtime",
          workerId: "unexpected-worker",
          name: "Runtime widening",
        }),
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 422 });
  });

  it("T-AC-15 T08 binds a proof to its exact identity and dev/prod slot rather than the whole project", async () => {
    const development = await prepareAccess(fixture);
    const production = await prepareAccess(fixture, { environmentId: fixture.production.id });
    let delivered = false;
    await expect(
      fixture.broker.consumeStatic(development.proof, production.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toMatchObject({ status: 403 });
    expect(delivered).toBe(false);
    await fixture.broker.consumeStatic(development.proof, development.slot.id, (value) => {
      delivered = value === development.value;
    });
    expect(delivered).toBe(true);
  });

  it("T-AC-15 T08 rotates only the selected proof and invalidates its prior access immediately", async () => {
    const first = await prepareAccess(fixture);
    const unaffected = await prepareAccess(fixture);
    let replacement = "";
    await fixture.broker.issueProof(
      fixture.freshOwner(),
      first.identity.id,
      first.identity.revision,
      randomUUID(),
      (proof) => {
        replacement = proof;
      },
    );
    await expect(
      fixture.broker.consumeStatic(first.proof, first.slot.id, () => undefined),
    ).rejects.toMatchObject({ status: 401 });
    let changedDelivered = false;
    let unaffectedDelivered = false;
    await fixture.broker.consumeStatic(replacement, first.slot.id, (value) => {
      changedDelivered = value === first.value;
    });
    await fixture.broker.consumeStatic(unaffected.proof, unaffected.slot.id, (value) => {
      unaffectedDelivered = value === unaffected.value;
    });
    expect(changedDelivered && unaffectedDelivered).toBe(true);
  });

  it("T-AC-15 T08 revokes broker access while preserving a visible pending upstream revocation", async () => {
    const access = await prepareAccess(fixture);
    const revoked = await fixture.broker.revokeIdentity(
      fixture.freshOwner(),
      access.identity.id,
      access.identity.revision,
      randomUUID(),
    );
    expect(revoked).toMatchObject({
      status: "revoked",
      upstreamRevocation: "pending",
      proofIssued: false,
    });
    let delivered = false;
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toMatchObject({ status: 401 });
    expect(delivered).toBe(false);
    expect(fixture.materialProvider.versions.size).toBe(1);
  });

  it("T-AC-15 T22 expires a service proof and refuses issuance for the expired identity", async () => {
    const access = await prepareAccess(fixture, {
      expiresAt: new Date(fixture.clock.now().getTime() + 1000).toISOString(),
    });
    fixture.clock.advance(1001);
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => undefined),
    ).rejects.toMatchObject({ status: 401 });
    await expect(
      fixture.broker.issueProof(
        fixture.freshOwner(),
        access.identity.id,
        access.identity.revision,
        randomUUID(),
        () => undefined,
      ),
    ).rejects.toMatchObject({ status: 403 });
  });

  it("T-AC-15 T22 rejects a prior-cell activation epoch even for a previously active runtime proof", async () => {
    const access = await prepareAccess(fixture);
    await fixture.engine.advanceEpoch(fixture.freshOwner(), fixture.development.id, randomUUID());
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => undefined),
    ).rejects.toMatchObject({ status: 401 });
  });

  it("T-AC-14 T37 converges concurrent identity creation and safely replays a lost private proof handoff", async () => {
    const key = randomUUID();
    const input = {
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      purpose: "runtime" as const,
      name: "Idempotent identity",
    };
    const [first, second] = await Promise.all([
      fixture.broker.createIdentity(fixture.freshOwner(), input, key),
      fixture.broker.createIdentity(fixture.freshOwner(), input, key),
    ]);
    expect(first.id).toBe(second.id);
    const handoffKey = randomUUID();
    let lost = "";
    await expect(
      fixture.broker.issueProof(
        fixture.freshOwner(),
        first.id,
        first.revision,
        handoffKey,
        (proof) => {
          lost = proof;
          throw new Error("Private fixture consumer was interrupted");
        },
      ),
    ).rejects.toMatchObject({ code: "PRIVATE_HANDOFF_FAILED" });
    let replayed = "";
    await fixture.broker.issueProof(
      fixture.freshOwner(),
      first.id,
      first.revision,
      handoffKey,
      (proof) => {
        replayed = proof;
      },
    );
    expect(Boolean(lost) && replayed === lost).toBe(true);
    await expect(
      fixture.broker.createIdentity(
        fixture.freshOwner(),
        { ...input, name: "Changed identity" },
        key,
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect((await fixture.broker.overview(fixture.freshOwner())).identities).toHaveLength(1);
  });

  it("T-AC-14 T08 keeps material and service proofs out of metadata, control rows and audit", async () => {
    const access = await prepareAccess(fixture);
    const inspected = JSON.stringify({
      overview: await fixture.broker.overview(fixture.freshOwner()),
      identities: await fixture.store.db.select().from(schema.serviceIdentities),
      slots: await fixture.store.db.select().from(schema.accessSlots),
      effects: await fixture.store.db.select().from(schema.accessOperations),
      receipts: await fixture.store.db.select().from(schema.foundationRequests),
      audit: await fixture.core.listAudit(owner),
    });
    expect(inspected.includes(access.value) || inspected.includes(access.proof)).toBe(false);
  });

  it("T-AC-15 T08 rejects altered provider material even when its version and copied metadata are unchanged", async () => {
    const access = await prepareAccess(fixture);
    const stored = [...fixture.materialProvider.versions.values()][0]?.[0];
    if (!stored) throw new Error("Provider fixture version missing");
    stored.value = randomUUID();
    let delivered = false;
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toMatchObject({ code: "PROVIDER_INVALID" });
    expect(delivered).toBe(false);
  });

  for (const mode of ["synchronous", "async"] as const) {
    it(`T-AC-14 T08 preserves a durable metadata-only attempt after a ${mode} consumer copies material then fails`, async () => {
      const access = await prepareAccess(fixture);
      const previous = await fixture.core.listAudit(owner);
      const previousSequence = Math.max(0, ...previous.map((entry) => entry.sequence));
      let copied = false;
      const [result] = await Promise.allSettled([
        fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
          copied = value === access.value;
          if (mode === "async") return Promise.reject(new Error(value));
          throw new Error(value);
        }),
      ]);
      expect(copied).toBe(true);
      const reason: unknown = result?.status === "rejected" ? result.reason : undefined;
      expect(
        Boolean(
          reason &&
            typeof reason === "object" &&
            "code" in reason &&
            reason.code === "PRIVATE_HANDOFF_FAILED",
        ),
      ).toBe(true);
      const message = reason instanceof Error ? reason.message : "";
      expect(message.includes(access.value) || message.includes(access.proof)).toBe(false);
      const events = (await fixture.core.listAudit(owner)).filter(
        (entry) => entry.sequence > previousSequence,
      );
      expect(events.some((entry) => entry.action === "access.material.handoff_attempted")).toBe(
        true,
      );
      expect(events.some((entry) => entry.action === "access.material.handoff_unknown")).toBe(true);
      expect(events.some((entry) => entry.action === "access.material.delivered")).toBe(false);
      const recorded = JSON.stringify(events);
      expect(recorded.includes(access.value) || recorded.includes(access.proof)).toBe(false);
    });
  }
});
